 const pre=body=>[...body.matchAll(/<pre\b[^>]*>[\s\S]*?<\/pre>/g)].map(m=>m[0]);
 const code=(body,index=0)=>[...body.matchAll(/<div class="code-block">[\s\S]*?<\/pre><\/div>/g)][index]?.[0]||'';
 const figure=(body,index=0)=>[...body.matchAll(/<figure\b[\s\S]*?<\/figure>/g)][index]?.[0]||'';
